import{z as o,x as i,o as A,c as d,q as l,j as n,D as E,d as t,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"租赁与表外","description":"","frontmatter":{"title":"租赁与表外","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lease-off-balance.md","filePath":"quant/lease-off-balance.md","lastUpdated":1791413859000}'),p={name:"quant/lease-off-balance.md"};function D(F,a,m,h,u,f){const B=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=l('<h1 id="租赁与表外" tabindex="-1">租赁与表外 <a class="header-anchor" href="#租赁与表外" aria-label="Permalink to &quot;租赁与表外&quot;">​</a></h1><div class="epigraph"><p>经营租赁曾把使用权资产与负债留在表外，杠杆与投资因子被系统性写小；入表之后，同一经济租赁变成资产增长与账面变厚。</p><footer>—— 据 IFRS 16 / ASC 842；Penman 对表外融资的讨论整理</footer></div><p>上一课<a href="/quant/segment-geo">分部与地域</a>修正了合并加总的业务构成。租赁修正的是合并加总的<strong>杠杆与资产</strong>。上一课因子索引里，投资常用总资产增长，价值用账面，盈利用利润表；经营租赁的会计选择会同时推动这三张表。本课只补表外变表内这一口径，不写租赁准则百科，也不进入下一课的合并范围。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IFRS 16 与 ASC 842 之前，经营租赁的租金进利润表，承诺付款在附注。资产与有息负债偏低，资产增长率偏低，账面可能偏高或偏低取决于累计费用模式。准则切换后，使用权资产与租赁负债入表，投资因子出现一次性跳升，杠杆与覆盖率一起变。若时间序列不声明准则断点，因子会把「会计入表」当成真实加杠杆。缺口是：比较租赁密集公司时，要么把表外承诺资本化（用当时附注），要么承认断点，禁止用新准则重述去改写旧年还假装连续。</p><p><span class="marginnote">术语翻译：经营租赁就是「租来用、但不买」——公司按期付租金，资产不记在自己名下，旧准则下报表里只有一笔租金费用，承诺的多年付款只躺在附注里。入表后，会计把这串承诺折成「使用权资产」与「租赁负债」记进主表，看上去就像借债买了个资产。</span></p><h3 id="资本化附注不是-restated-主表" tabindex="-1">资本化附注不是 restated 主表 <a class="header-anchor" href="#资本化附注不是-restated-主表" aria-label="Permalink to &quot;资本化附注不是 restated 主表&quot;">​</a></h3><p>用今天已经按 IFRS 16 重述的历史资产负债表回填 2016 年，是 PIT 违规：2016 年交易者看到的是表外附注，不是后来的使用权资产。允许的做法是：在 2016 年用当时附注的最低租赁付款额自行折现资本化——折现率与年限必须用当时可获得的信息，不能用后来才披露的增量借款利率回填。</p><p><span class="marginnote">零售、航空、电信对这条最敏感。行业中性只能部分吸收：同行业里租赁政策仍可不同，断点年仍会集体跳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复制官方 Fama–French 时，按他们当时能用的 Compustat 主表，不要私自用新准则重述去「改进」历史 HML。自建投资/杠杆因子则声明：表外租赁是否资本化、折现规则、可用日期取年报附注。准则切换年把受影响公司单独标记或做断点调整，避免资产增长因子在切换年全体做空租赁密集股。盈利侧：租金费用变为折旧加利息后，EBIT 与 EBITDA 含义改变，口径要与分析师共识对齐，否则惊喜被准则切换污染。</p>',11)),(A(),n(s,null,{default:E(()=>[r(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E8%A1%A8%E5%A4%96%E7%BB%8F%E8%90%A5%E7%A7%9F%E8%B5%81%22%5D%20--%3E%20NOTE%5B%22%E9%99%84%E6%B3%A8%E6%89%BF%E8%AF%BA%E4%BB%98%E6%AC%BE%22%5D%0A%20%20NOTE%20--%3E%20CAP%5B%22%E5%BD%93%E6%97%B6%E4%BF%A1%E6%81%AF%E8%B5%84%E6%9C%AC%E5%8C%96%22%5D%0A%20%20ON%5B%22%E5%85%A5%E8%A1%A8%E4%BD%BF%E7%94%A8%E6%9D%83%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20BS%5B%22%E8%B5%84%E4%BA%A7%E4%B8%8E%E8%B4%9F%E5%80%BA%E8%B7%B3%E5%8D%87%22%5D%0A%20%20REST%5B%22%E4%BA%8B%E5%90%8E%E9%87%8D%E8%BF%B0%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20LEAK%5B%22%E5%89%8D%E8%A7%86%E5%8F%A3%E5%BE%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"官方因子复制用当时主表；自建杠杆才允许当时附注资本化。IFRS 16 重述余额不得回写切换前年份。切换年租赁密集行业单独报告。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"表外融资让杠杆因子、违约距离、资产增长同时偏小，质量应计相对少受影响（租金多为经营流出）。入表后，投资与价值被一次性改写，真实租赁合同未必变。这是会计身份推动因子共线的又一例，与商誉并购对称：一次计量规则改变，多条信号同跳。资金与保证金课会把杠杆当成可交易约束；这里的杠杆还只是报表口径，尚未变成经纪商保证金。",-1)),(A(),n(s,null,{default:E(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22IFRS%2016%20%2F%20ASC%20842%20%E5%88%87%E6%8D%A2%22%5D%20--%3E%20A%5B%22%E4%BD%BF%E7%94%A8%E6%9D%83%E8%B5%84%E4%BA%A7%E5%85%A5%E8%A1%A8%22%5D%0A%20%20SW%20--%3E%20L%5B%22%E7%A7%9F%E8%B5%81%E8%B4%9F%E5%80%BA%E5%85%A5%E8%A1%A8%22%5D%0A%20%20A%20--%3E%20INV%5B%22%E6%8A%95%E8%B5%84%E5%9B%A0%E5%AD%90%EF%BC%9A%E6%80%BB%E8%B5%84%E4%BA%A7%E4%B8%80%E6%AC%A1%E6%80%A7%E8%B7%B3%E5%8D%87%22%5D%0A%20%20L%20--%3E%20LEV%5B%22%E6%9D%A0%E6%9D%86%E4%B8%8E%E8%A6%86%E7%9B%96%E7%8E%87%E5%90%8C%E6%AD%A5%E6%94%B9%E5%8F%98%22%5D%0A%20%20A%20--%3E%20E%5B%22%E7%A7%9F%E9%87%91%E8%B4%B9%E7%94%A8%E5%8F%98%E4%B8%BA%E6%8A%98%E6%97%A7%E5%8A%A0%E5%88%A9%E6%81%AF%E5%8F%A3%E5%BE%84%22%5D%0A%20%20E%20--%3E%20PR%5B%22%E7%9B%88%E5%88%A9%E5%9B%A0%E5%AD%90%E4%B8%8E%E5%88%86%E6%9E%90%E5%B8%88%E5%85%B1%E8%AF%86%E9%94%99%E4%BD%8D%22%5D%0A%20%20INV%20--%3E%20F%5B%22%E8%A2%AB%E8%AF%AF%E8%AF%BB%E4%B8%BA%E7%9C%9F%E5%AE%9E%E5%8A%A0%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">不要把本课读成「杠杆越高 alpha 越高」。对象是口径偏差与回测断点，不是杠杆溢价理论。</span></p><p>复制官方因子：跟随当时 Compustat 主表，准则切换年做断点标记。自建杠杆或投资因子：若资本化表外承诺，折现率与剩余年限只用当时附注与当时利率，禁止用 IFRS 16 重述余额回写 2015 年。切换年把零售、航空等租赁密集行业单独报告，避免投资因子的空头被会计跳升填满。EBIT 与 EBITDA 在入表后与 IBES 口径对齐，再算惊喜。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不汇编 IFRS 16 条款，不估房地产重置。下一课<a href="/quant/nci-consolidation">合并与少数股东</a>处理谁被加进合并表，与租赁谁被加进资产是不同问题。后课默认：投资与杠杆因子已声明租赁口径与准则断点；禁止用新准则 restated 主表冒充历史 PIT。</p><p>后课 NCI 处理谁被合并；本课处理哪些租赁被资本化。两条修正不要合成一个「调整后资产」却不留痕迹。准则切换年在投资因子里单独报告。复制 French 库时继续用当时主表，自建杠杆因子才允许当时附注资本化，两套结果不要混称为同一个 HML。</p><p>后课默认投资与杠杆已声明租赁口径与准则断点；禁止用新准则 restated 主表冒充历史 PIT。</p><p>入表后 EBITDA 上升、利息上升，分析师若仍用旧口径，惊喜会被准则切换污染。本课要求在切换年把口径对齐声明写进惊喜来源卡，而不是把跳跃解释成经营改善。</p><p><span class="marginnote">数字实例：一家航空公司 10 年每年付 1 亿元租金。表外时代它只表现为每年 1 亿元费用；按 IFRS 16 用 5% 折现，入表时一次性记上约 7.7 亿元的租赁负债与等额使用权资产——资产负债率立刻跳升，而公司的真实义务一分未变。这就是「会计跳变」与「真实加杠杆」的区别。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经营租赁曾表外，资产增长与杠杆被写小。</li><li>入表造成一次性跳升，不是经济上突然加杠杆。</li><li>用当时附注资本化可以，用事后重述回填不可以。</li><li>官方因子复制应跟随当时主表，不要私自「改进历史」。</li><li>EBIT 口径在入表后与分析师共识要对齐。</li><li>出处：IFRS 16 / ASC 842；Penman 表外融资。</li></ul>',10))])}const T=o(p,[["render",D]]);export{S as __pageData,T as default};
